import datetime
def skew(sec):
    def f(t):
        d=datetime.datetime.strptime(t,'%Y-%m-%dT%H:%M:%S.%fZ')+datetime.timedelta(seconds=sec)
        return d.strftime('%Y-%m-%dT%H:%M:%S.%f')[:-3]+'Z'
    return f
