recs=[r for r in recs if r.get('kind')=='bash_command']
by_tr=collections.defaultdict(list)
for r in recs: by_tr[r.get('transcript')].append(r)

for tr,rs in by_tr.items():
    d=os.path.dirname(tr); sid=os.path.basename(tr)[:-6]
    subs=sorted(glob.glob(os.path.join(d,sid,'subagents','**','*.jsonl'),recursive=True))
    t0=time.perf_counter(); main=index_file(tr); t_main=(time.perf_counter()-t0)*1000
    t0=time.perf_counter()
    allm=dict(main)
    for s in subs: allm.update(index_file(s))
    t_all=(time.perf_counter()-t0)*1000
    # command -> id, from all files
    cmd2id={}
    for p in [tr]+subs:
        for line in open(p,'r',encoding='utf-8',errors='replace'):
            if '"tool_use"' not in line: continue
            try: rr=json.loads(line)
            except ValueError: continue
            for b in (rr.get('message') or {}).get('content') or []:
                if isinstance(b,dict) and b.get('type')=='tool_use' and b.get('name')=='Bash':
                    cc=(b.get('input') or {}).get('command')
                    if isinstance(cc,str): cmd2id.setdefault(cc,b['id'])
    hit_main=sum(1 for r in rs if cmd2id.get(r['command']) in main)
    hit_all =sum(1 for r in rs if cmd2id.get(r['command']) in allm)
    print('%s  recs=%-4d subagent_files=%-4d  id-in-main=%-4d  id-in-main+subs=%-4d  index_ms main=%.1f all=%.1f  mainMB=%.1f allMB=%.1f'
          % (sid[:8], len(rs), len(subs), hit_main, hit_all, t_main, t_all,
             os.path.getsize(tr)/1e6, sum(os.path.getsize(x) for x in [tr]+subs)/1e6))

